def json_equal(a,b):
 if isinstance(a,bool) or isinstance(b,bool):return isinstance(a,bool) and isinstance(b,bool) and a==b
 if isinstance(a,(int,float)) and isinstance(b,(int,float)):return a==b
 if type(a)!=type(b):return False
 if isinstance(a,dict):return a.keys()==b.keys() and all(json_equal(a[k],b[k]) for k in a)
 if isinstance(a,list):return len(a)==len(b) and all(json_equal(x,y) for x,y in zip(a,b))
 return a==b

def signature_unknown(v):
 if unknown(v):return True
 if isinstance(v,list):return any(signature_unknown(item) for item in v)
 if isinstance(v,dict):return any(signature_unknown(item) for item in v.values())
 return False

def compare_f01(packet,context):
 results={};targets=packet.get('targets');vocab=packet.get('role_vocabulary');evaluation=packet.get('evaluation_date')
 if isinstance(targets,list):
  for t in targets:
   role=t.get('declared_role')
   if missing(role) or unknown(role) or not isinstance(vocab,list) or role not in vocab:state='unknown_role'
   elif missing(t.get('meaning')) or unknown(t.get('meaning')):state='missing_target_meaning'
   elif missing(t.get('role_basis')) or unknown(t.get('role_basis')):state='missing_basis'
   elif not isinstance(t.get('consumers'),list) or not t['consumers'] or any(missing(v) for v in t['consumers']):state='missing_consumer'
   elif any(unknown(v) for v in t['consumers']):state='unknown_consumer'
   elif t.get('name') in ['Manager','Helper','Util','Data']:
    es=exception_state(t.get('exception'),context['scope'],evaluation)
    state='candidate_only:'+role+'_with_scoped_exception' if es=='valid_for_fixture_scope' else 'missing_scoped_exception'
   else:state='candidate_only:'+role
   results[t['id']]=state
 return {'target_results':results,'canonical_decided_here':False,**common(context)}

def compare_f02(packet,context):
 stable=packet.get('stable_object');oracle=packet.get('stable_oracle');operation=packet.get('operation');before=packet.get('before');after=packet.get('after')
 results={'object_identity':identity_state(stable,before,after,'object'),'oracle_identity':identity_state(oracle,before,after,'oracle')}
 results['symbol_edge']=edge_state(packet.get('symbol_edge'),{'object':stable,'operation':operation,'symbol':obj(after).get('symbol')})
 results['oracle_edge']=edge_state(packet.get('oracle_edge'),{'object':stable,'operation':operation,'oracle':oracle})
 p=packet.get('pair');pair_states=[compare_value(obj(p).get(k),stable,'same_object') for k in ['requirement_object','verification_object']]
 results['pair']=next((s for s in ['missing','unknown','conflict'] if s in pair_states),'same_object')
 return {'edge_results':results,'symbol_change':'candidate_only',**common(context)}

def origin_state(actual,required):
 states=[]
 for key in ['owner','revision']:
  state=compare_value(obj(actual).get(key),obj(required).get(key),'known')
  if state=='conflict' and key=='revision':state='stale'
  states.append(state)
 return next((s for s in ['missing','unknown','stale','conflict'] if s in states),'known')

def compare_f04(packet,context):
 finding=obj(packet.get('finding'));boundary=packet.get('boundary')
 route='Redesign_or_Retrofit_with_compatibility_migration' if boundary in OBSERVABLE else 'product_author' if boundary=='internal' else 'unknown'
 e=exception_state(packet.get('exception'),packet.get('scope'),packet.get('evaluation_date'))
 return {'auto_rename':'rejected','return_candidate':route,'finding_retained':finding.get('id'),'exception_result':e,'local_continuation':e=='valid_for_fixture_scope','global_stop':False,**common(context)}

def compare_b01(packet,context):
 norm=obj(packet.get('norm_source'));product=obj(packet.get('product_decision'));proposal=obj(packet.get('proposal'));before=obj(packet.get('protected_before'));after=obj(packet.get('protected_after'))
 results={};owners=[]
 for key,actual,required,owner in [('norm',proposal.get('norm_content'),norm.get('content'),'HARNESS-norm-owner'),('product_decision',proposal.get('product_name'),product.get('content'),'product-design-owner')]:
  state=compare_value(actual,required,'held');results[key]='rejected' if state=='conflict' else state
  origin=origin_state(norm if key=='norm' else product,context['origin_requirements'][key])
  if origin!='known':results[key]='rejected' if origin=='conflict' else origin
  if results[key]!='held':owners.append(owner)
 ci=proposal.get('CI_effect');results['CI']='missing' if missing(ci) else 'unknown' if unknown(ci) else 'candidate_only' if ci=='finding_only' else 'rejected'
 if results['CI']!='candidate_only':owners.append('CI-boundary-owner')
 for key in ['requirement_id','mechanism_role','adopted_body']:
  state=compare_value(after.get(key),before.get(key),'held');results[key]='out_of_scope_change_rejected' if state=='conflict' else state
  if state!='held' and 'original-meaning-owner' not in owners:owners.append('original-meaning-owner')
 return {'boundary_results':results,'owner_return_candidates':owners,**common(context)}

def compare_source_attributes(actual,required):
 result={}
 for key in ATTRS:
  a=obj(actual).get(key);r=obj(required).get(key)
  state=compare_value(a,r,'known')
  if state=='conflict' and key=='revision':state='stale'
  result[key]=state
 return {'attribute_results':result,'actual_qualification_established':False,'qualification_provider':{'state':'unknown','value':None}}

