   author_returns.append({'target_index':target_index,'target_id':target_id,'recipient_role':'target_creator','reason':reason,'target_pointer':'/arguments/packet/targets/'+str(target_index),'comparison_pointer':'/comparison/target_results/'+escaped_id})
