def compare_f03_source_bound_candidate(packet,context,basis):
 input_capture={'arguments':{'packet':copy.deepcopy(packet),'context':copy.deepcopy(context)},'basis':copy.deepcopy(basis)}
 native_return=compare_f03(packet,context)
 source_attribute_results={}
 for role in declared11_role_order:
  source_attribute_results[role]=compare_source_attributes(basis['sources'][role]['attributes'],basis['source_requirements'][role])
 binding_results={}
 for role in declared11_role_order:
  src=basis['sources'][role]
  field=role_to_packet_field[role]
  value_result=compare_value(src['value'],packet[field],'same_value')
  subject_results={'identity':compare_value(src['subject']['identity'],basis['selected_target']['identity'],'known'),
                   'revision':compare_value(src['subject']['revision'],basis['selected_target']['revision'],'known'),
                   'scope':compare_value(src['subject']['scope'],basis['selected_target']['scope'],'known')}
  if subject_results['revision']=='conflict':
   subject_results['revision']='stale'
  binding_results[role]={'argument_pointer':'/input_capture/arguments/packet/'+field,'source_pointer':'/input_capture/basis/sources/'+role,'value_result':value_result,'subject_results':subject_results}
 diagnostic_refs=[]
 for role in declared11_role_order:
  sr=source_attribute_results[role]
  for fname in ('identity','revision','scope','condition'):
   if isinstance(sr,dict) and fname in sr and sr[fname]!='known' and sr[fname]!='supported_synthetic_condition':
    diagnostic_refs.append('/source_attribute_results/'+role+'/'+fname)
  br=binding_results[role]
  if br['value_result']!='same_value':
   diagnostic_refs.append('/binding_results/'+role+'/value_result')
  for f in ('identity','revision','scope'):
   if br['subject_results'][f] not in ('known','stale'):
    diagnostic_refs.append('/binding_results/'+role+'/subject_results/'+f)
   elif f=='revision' and br['subject_results'][f]=='stale':
    diagnostic_refs.append('/binding_results/'+role+'/subject_results/revision')
 target_scope_result=compare_value(basis['selected_target']['scope'],context['scope'],'known')
 if target_scope_result!='known':
  diagnostic_refs.append('/target_scope_result')
 if not native_return['candidate_presentable']:
  for ckey in native_return['condition_results']:
   if native_return['condition_results'][ckey]!='supported_synthetic_condition':
    diagnostic_refs.append('/native_return/condition_results/'+ckey)
 if len(diagnostic_refs)>0:
  presentation={'state':'not_presentable','diagnostic_refs':diagnostic_refs}
 else:
  presentation={'state':'source_bound_candidate_only','diagnostic_refs':diagnostic_refs}
 author_returns=[]
 for role in declared11_role_order:
  br=binding_results[role]
  refs=[]
  if br['value_result']!='same_value':
   refs.append('/binding_results/'+role+'/value_result')
  for f in ('identity','revision','scope'):
   if br['subject_results'][f]!='known':
    refs.append('/binding_results/'+role+'/subject_results/'+f)
  for ref in refs:
   author_returns.append({'recipient_role':'target_creator','target_pointer':'/input_capture/basis/selected_target','condition_role':role,'reason_pointer':ref})
 actual_dispatch=False
 return {'input_capture':input_capture,'native_return':native_return,'source_attribute_results':source_attribute_results,'binding_results':binding_results,'presentation':presentation,'author_returns':author_returns,'actual_dispatch':actual_dispatch,'target_scope_result':target_scope_result}
